//! The 131 music types (04 §6.1): [`TYPES`], generated by `build.rs` from
//! the installed `define-music-types.scm`, and the C++ callbacks their
//! properties name that the engine does not have yet: [`PLACEHOLDERS`]
//! (D67).
//!
//! A type's number, its *kind*, is its index in [`TYPES`], which is sorted by
//! name as `music-descriptions` is. Its properties become Scheme values when
//! [`define_music_types`] evaluates them in `(lily)`, as the file's
//! quasiquote does when LilyPond loads it.

use alloc::string::String;

use lily_engine_scheme::{Cx, Prim, Thrown, Value, Vm};

/// A music type as `music-descriptions` gives it.
pub struct MusicType {
    pub name: &'static str,
    /// Its `types`: `["event", "note-event", "rhythmic-event", …]`.
    pub types: &'static [&'static str],
    /// Its properties in the file's order, `description` left out: each key
    /// with the Scheme text of its value, quoted unless it was unquoted.
    pub props: &'static [(&'static str, &'static str)],
}

include!(concat!(env!("OUT_DIR"), "/music_types.rs"));

/// The kind of the type named `name`.
pub fn kind(name: &str) -> Option<u8> {
    let i = TYPES.binary_search_by(|t| t.name.cmp(name)).ok()?;
    u8::try_from(i).ok()
}

/// Sets `%music-properties` in `vm`'s `(lily)`, the table `make-music`
/// takes a type's properties from, as `music-name-to-property-table` holds
/// them: `((name . Name) (types . …) …)` for each type, with what the file
/// unquotes evaluated; and `music-name-to-property-table` of them, in which
/// the `display` part keeps its methods. That needs [`PLACEHOLDERS`], `lily-library.scm`'s
/// `ZERO-MOMENT` and `define-music-callbacks.scm`'s procedures, which
/// LilyPond loads before the file.
pub fn define_music_types(vm: &mut Vm) -> Result<usize, String> {
    let mut text = String::from("(list");
    for t in &TYPES {
        text.push_str("\n (list '");
        text.push_str(t.name);
        text.push_str(" (cons 'name '");
        text.push_str(t.name);
        text.push(')');
        for (key, value) in t.props {
            text.push_str(" (cons '");
            text.push_str(key);
            text.push(' ');
            text.push_str(value);
            text.push(')');
        }
        text.push(')');
    }
    text.push(')');
    let lily = vm
        .eval_text("(resolve-module '(lily))", None)
        .map_err(|e| e.text(vm.heap()))?;
    let table = vm
        .eval_text(
            &alloc::format!(
                "(define-public %music-properties {text})
                 (define-public music-name-to-property-table (make-hash-table 59))
                 (for-each (lambda (e) (hashq-set! music-name-to-property-table (car e) (cdr e)))
                           %music-properties)
                 %music-properties"
            ),
            None,
        )
        .map_err(|e| e.text(vm.heap()))?;
    vm.module_define(lily, "%music-properties", table);
    Ok(TYPES.len())
}

/// What the error of a placeholder says brings it.
pub struct Placeholder {
    pub name: &'static str,
    pub arity: u8,
    /// The step or milestone that replaces it: `MS2 step 3`, `N4`.
    pub by: &'static str,
}

const fn ph(name: &'static str, arity: u8, by: &'static str) -> Placeholder {
    Placeholder { name, arity, by }
}

/// The C++ callbacks `define-music-types.scm` names that the engine does not
/// have yet, and the quote iterator's constructor, with LilyPond 2.26.0's arities, and the step that brings each
/// (04 §13; MS2's plan in progress.md). Each is a primitive of
/// [`crate::install`] that throws `misc-error` when called (D67). The
/// lengths' and starts' are `length.rs`' [`crate::CALLBACKS`], and
/// `\relative`'s `relative.rs`' [`crate::RELATIVE_CALLBACKS`].
pub static PLACEHOLDERS: [Placeholder; 25] = [
    // Iterators.
    ph("ly:apply-context-iterator::constructor", 0, "N4"),
    ph("ly:context-specced-music-iterator::constructor", 0, "N4"),
    ph("ly:event-chord-iterator::constructor", 0, "N4"),
    ph("ly:initial-context-music-iterator::constructor", 0, "N4"),
    ph("ly:music-iterator::constructor", 0, "N4"),
    ph("ly:music-wrapper-iterator::constructor", 0, "N4"),
    ph("ly:pop-property-iterator::constructor", 0, "N4"),
    ph("ly:property-iterator::constructor", 0, "N4"),
    ph("ly:property-unset-iterator::constructor", 0, "N4"),
    ph("ly:push-property-iterator::constructor", 0, "N4"),
    ph("ly:rhythmic-music-iterator::constructor", 0, "N4"),
    ph("ly:sequential-iterator::constructor", 0, "N4"),
    ph("ly:simple-music-iterator::constructor", 0, "N4"),
    ph("ly:simultaneous-music-iterator::constructor", 0, "N4"),
    ph("ly:tuplet-iterator::constructor", 0, "N4"),
    ph("ly:change-iterator::constructor", 0, "N6"),
    ph("ly:grace-iterator::constructor", 0, "N6"),
    ph("ly:alternative-sequence-iterator::constructor", 0, "N7"),
    ph("ly:lyric-combine-music-iterator::constructor", 0, "N7"),
    ph("ly:volta-repeat-iterator::constructor", 0, "N7"),
    ph("ly:volta-specced-music-iterator::constructor", 0, "N7"),
    // What no score reaches (04 §13): after N7.
    ph("ly:fine-iterator::constructor", 0, "MS5 step 6"),
    ph("ly:part-combine-iterator::constructor", 0, "MS5 step 6a"),
    ph("ly:percent-repeat-iterator::constructor", 0, "MS5 step 6"),
    // Named by no type but by `music-functions.scm`'s `quote-substitute`,
    // which puts it on a `\quoteDuring`'s music: MS8 step 10.
    ph("ly:quote-iterator::constructor", 0, "MS8 step 10"),
];

/// The primitive of [`PLACEHOLDERS`]' `i`th entry.
pub(crate) const fn placeholder_prim(i: usize, f: lily_engine_scheme::PrimFn) -> Prim {
    let p = &PLACEHOLDERS[i];
    Prim {
        name: p.name,
        min: p.arity,
        max: p.arity,
        f,
    }
}

/// A placeholder's call: `misc-error` from the primitive, naming what
/// brings it.
#[cold]
pub(crate) fn unimplemented(cx: &mut Cx, i: usize) -> Result<Value, Thrown> {
    let p = &PLACEHOLDERS[i];
    let message = alloc::format!("not in the engine before {}", p.by);
    Err(cx.error("misc-error", Some(p.name), &message, &[]))
}
